   JsonObject frame=new JsonObject();frame.addProperty("action",new String[]{"idle","walk","crouch","glide"}[pose]);frame.addProperty("time",20*pose);JsonArray faces=new JsonArray();for(int i=0;i<capture.vertices.size();i+=4){JsonArray face=new JsonArray();for(int j=0;j<4;j++){var v=capture.vertices.get(i+j);JsonArray p=new JsonArray();for(int k=0;k<5;k++){check(Float.isFinite(v[k])&&(k<3||v[k]>=0&&v[k]<=1),"finite native coordinate/UV");p.add(k<3?v[k]*16:v[k]);}face.add(p);}faces.add(face);}frame.add("faces",faces);frames.add(frame);
